import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';
import { isValidDate } from './dates.js';

/**
 * Create a new draft invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }> }}
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  // Normalize customer ID
  const normalizedCustomerId = normalizeId(customerId);

  // Validate customer exists
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  // Validate issueDate is in YYYY-MM-DD format
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  // Validate lines is not empty
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Process lines and validate each
  const processedLines = [];
  for (const line of lines) {
    // Validate qty is a positive integer
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    // Determine discountPercent: use explicit value if provided, otherwise use tier discount
    let discountPercent;
    if (line.hasOwnProperty('discountPercent')) {
      // Explicit value provided (even if 0)
      discountPercent = line.discountPercent;
      if (typeof discountPercent !== 'number' || discountPercent < 0 || discountPercent > 100) {
        return fail('DISCOUNT_INVALID');
      }
    } else {
      // No explicit value, use customer tier discount
      discountPercent = TIER_DISCOUNTS[customerResult.value.tier];
    }

    // Get product
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    processedLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent
    });
  }

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    lines: processedLines
  });
}

/**
 * Calculate the total amount for a line item (qty × unitPrice in cents).
 * @param {{ qty: number, unitPrice: number }}
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate the discount amount for a line item (lineTotal × discountPercent / 100, clamped at 0).
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }}
 * @returns {number}
 */
export function lineDiscount(line) {
  const discountPercent = line.discountPercent ?? 0;
  const discount = roundCents(lineTotal(line) * discountPercent / 100);
  return Math.max(0, discount);
}

/**
 * Calculate the VAT amount for a line item (amount after discount × vatRate / 100, clamped at 0).
 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }}
 * @returns {number}
 */
export function lineVAT(line) {
  const amountAfterDiscount = lineTotal(line) - lineDiscount(line);
  const vat = roundCents(amountAfterDiscount * line.vatRate / 100);
  return Math.max(0, vat);
}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }> }}
 * @returns {{ subtotal: number, discount: number, vat: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0);
  const vat = invoice.lines.reduce((sum, line) => sum + lineVAT(line), 0);
  const total = Math.max(0, subtotal - discount + vat);
  return { subtotal, discount, vat, total };
}

/**
 * Add a line to an invoice, or increase qty if the SKU already exists.
 * @param {{ status: string, customerId: string, lines: Array<{ sku: string, qty: number, name: string, unitPrice: number, vatRate: number, discountPercent?: number }> }}, { sku: string, qty: number, discountPercent?: number }}
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  // Check invoice is in draft status
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Validate qty is a positive integer
  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  // Determine discountPercent: use explicit value if provided, otherwise use tier discount
  let finalDiscount;
  if (discountPercent !== undefined) {
    // Explicit value provided (even if 0)
    finalDiscount = discountPercent;
    if (typeof finalDiscount !== 'number' || finalDiscount < 0 || finalDiscount > 100) {
      return fail('DISCOUNT_INVALID');
    }
  } else {
    // No explicit value, use customer tier discount
    const customerResult = getCustomer(normalizeId(invoice.customerId));
    if (!customerResult.ok) return customerResult;
    finalDiscount = TIER_DISCOUNTS[customerResult.value.tier];
  }

  // Get product and validate SKU exists
  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));

  // Check if SKU already exists
  const existingIndex = newLines.findIndex((line) => line.sku === sku);

  if (existingIndex !== -1) {
    // Increase qty on existing line
    newLines[existingIndex].qty += qty;
  } else {
    // Add new line at the end
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: finalDiscount
    });
  }

  return ok({
    ...invoice,
    lines: newLines
  });
}

/**
 * Remove a line from an invoice by SKU.
 * @param {{ status: string, lines: Array<{ sku: string }> }}, string
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Check invoice is in draft status
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Check SKU exists on invoice
  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex === -1) return fail('LINE_NOT_FOUND');

  // Check it's not the last line
  if (invoice.lines.length === 1) return fail('NO_LINES');

  // Create new invoice without that line
  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    ...invoice,
    lines: newLines
  });
}

/**
 * Issue an invoice, assigning it a number and changing status to 'issued'.
 * @param {{ status: string, issueDate: string }}, Array<string>
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check invoice is in draft status
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    ...invoice,
    number,
    status: 'issued'
  });
}

