import test from 'node:test';
import assert from 'node:assert/strict';
import { isValidDate, addDays, daysBetween, getLastDayOfMonth } from '../src/dates.js';

test('isValidDate accepts valid dates', () => {
  assert.equal(isValidDate('2024-01-15'), true);
  assert.equal(isValidDate('2024-12-31'), true);
  assert.equal(isValidDate('2024-02-29'), true);
  assert.equal(isValidDate('2000-01-01'), true);
});

test('isValidDate rejects invalid formats', () => {
  assert.equal(isValidDate('01-15-2024'), false);
  assert.equal(isValidDate('2024/01/15'), false);
  assert.equal(isValidDate('2024-1-15'), false);
  assert.equal(isValidDate('2024-01-5'), false);
  assert.equal(isValidDate('24-01-15'), false);
});

test('isValidDate rejects non-existent dates', () => {
  assert.equal(isValidDate('2024-02-30'), false);
  assert.equal(isValidDate('2024-13-01'), false);
  assert.equal(isValidDate('2024-04-31'), false);
  assert.equal(isValidDate('2023-02-29'), false);
});

test('isValidDate rejects invalid input types', () => {
  assert.equal(isValidDate(null), false);
  assert.equal(isValidDate(undefined), false);
  assert.equal(isValidDate(12345), false);
  assert.equal(isValidDate({ date: '2024-01-15' }), false);
});

test('isValidDate rejects empty string', () => {
  assert.equal(isValidDate(''), false);
});

test('isValidDate rejects strings with whitespace', () => {
  assert.equal(isValidDate(' 2024-01-15'), false);
  assert.equal(isValidDate('2024-01-15 '), false);
  assert.equal(isValidDate(' 2024-01-15 '), false);
});

test('addDays adds positive days', () => {
  assert.equal(addDays('2024-01-15', 1), '2024-01-16');
  assert.equal(addDays('2024-01-15', 7), '2024-01-22');
  assert.equal(addDays('2024-01-31', 1), '2024-02-01');
});

test('addDays handles month boundaries', () => {
  assert.equal(addDays('2024-02-28', 1), '2024-02-29');
  assert.equal(addDays('2024-02-29', 1), '2024-03-01');
  assert.equal(addDays('2024-12-31', 1), '2025-01-01');
});

test('addDays subtracts negative days', () => {
  assert.equal(addDays('2024-01-15', -1), '2024-01-14');
  assert.equal(addDays('2024-02-01', -1), '2024-01-31');
  assert.equal(addDays('2025-01-01', -1), '2024-12-31');
});

test('addDays with zero days', () => {
  assert.equal(addDays('2024-01-15', 0), '2024-01-15');
});

test('addDays handles large offsets', () => {
  // 2024 is a leap year with 366 days
  assert.equal(addDays('2024-01-01', 365), '2024-12-31');
  assert.equal(addDays('2024-01-01', 366), '2025-01-01');
  // 366 + 365 = 731 days (2024 is leap, 2025 is not)
  assert.equal(addDays('2024-01-01', 731), '2026-01-01');
});

test('daysBetween calculates positive differences', () => {
  assert.equal(daysBetween('2024-01-15', '2024-01-16'), 1);
  assert.equal(daysBetween('2024-01-15', '2024-01-22'), 7);
  assert.equal(daysBetween('2024-01-31', '2024-02-01'), 1);
});

test('daysBetween handles month boundaries', () => {
  assert.equal(daysBetween('2024-02-28', '2024-02-29'), 1);
  assert.equal(daysBetween('2024-02-29', '2024-03-01'), 1);
  assert.equal(daysBetween('2024-12-31', '2025-01-01'), 1);
});

test('daysBetween calculates negative differences', () => {
  assert.equal(daysBetween('2024-01-16', '2024-01-15'), -1);
  assert.equal(daysBetween('2024-02-01', '2024-01-31'), -1);
  assert.equal(daysBetween('2025-01-01', '2024-01-01'), -366);
});

test('daysBetween with same dates', () => {
  assert.equal(daysBetween('2024-01-15', '2024-01-15'), 0);
});

test('daysBetween for year-long differences', () => {
  assert.equal(daysBetween('2024-01-01', '2025-01-01'), 366);
  assert.equal(daysBetween('2023-01-01', '2024-01-01'), 365);
});

test('addDays and daysBetween are consistent', () => {
  const start = '2024-01-15';
  const daysToAdd = 17;
  const end = addDays(start, daysToAdd);
  assert.equal(daysBetween(start, end), daysToAdd);
});

test('dates handle leap years correctly', () => {
  // 2024 is a leap year
  assert.equal(isValidDate('2024-02-29'), true);
  assert.equal(daysBetween('2024-01-01', '2024-12-31'), 365);
  assert.equal(daysBetween('2024-01-01', '2025-01-01'), 366);

  // 2023 is not a leap year
  assert.equal(isValidDate('2023-02-29'), false);
  assert.equal(daysBetween('2023-01-01', '2024-01-01'), 365);
});

test('dates work with century boundaries', () => {
  assert.equal(addDays('1999-12-31', 1), '2000-01-01');
  assert.equal(daysBetween('1999-12-31', '2000-01-01'), 1);
  assert.equal(addDays('2099-12-31', 1), '2100-01-01');
});
